import React, {
  useEffect,
  useRef,
  useState,
} from 'react';

import {
  FiPlus,
  FiEdit2,
  FiTrash2,
  FiUpload,
  FiUsers,
  FiX,
  FiImage,
  FiMail,
  FiPhone,
  FiGlobe,
  FiCheckCircle,
} from 'react-icons/fi';

import { toast } from 'react-toastify';

import api from './../../services/api';

import {
  useLanguage,
} from './../../contexts/LanguageContext';


const API_BASE_URL =
  process.env.REACT_APP_API_URL ||
  'http://127.0.0.1:8000';


const initialForm = {
  name_en: '',
  name_km: '',

  position_en: '',
  position_km: '',

  bio_en: '',
  bio_km: '',

  email: '',
  phone: '',

  facebook_url: '',
  linkedin_url: '',

  is_active: true,
  order: 0,
};


const AdminLeadership = () => {

  // ==========================================
  // LANGUAGE
  // ==========================================

  const {
    t,
    language,
  } = useLanguage();


  const isKhmer =
    language === 'km' ||
    language === 'kh';


  const tr = (
    key,
    englishFallback,
    khmerFallback
  ) => {

    const translated =
      t(key);


    if (
      translated &&
      translated !== key
    ) {
      return translated;
    }


    return isKhmer
      ? khmerFallback
      : englishFallback;
  };


  // ==========================================
  // CURRENT LANGUAGE FIELDS
  // ==========================================

  const nameField =
    isKhmer
      ? 'name_km'
      : 'name_en';


  const positionField =
    isKhmer
      ? 'position_km'
      : 'position_en';


  const bioField =
    isKhmer
      ? 'bio_km'
      : 'bio_en';


  // ==========================================
  // STATE
  // ==========================================

  const [
    members,
    setMembers,
  ] = useState([]);


  const [
    loading,
    setLoading,
  ] = useState(true);


  const [
    saving,
    setSaving,
  ] = useState(false);


  const [
    showModal,
    setShowModal,
  ] = useState(false);


  const [
    editingMember,
    setEditingMember,
  ] = useState(null);


  const [
    imageFile,
    setImageFile,
  ] = useState(null);


  const [
    imagePreview,
    setImagePreview,
  ] = useState(null);


  const [
    imageRemoved,
    setImageRemoved,
  ] = useState(false);


  const [
    formData,
    setFormData,
  ] = useState({
    ...initialForm,
  });


  const fileInputRef =
    useRef(null);


  // ==========================================
  // IMAGE URL
  // ==========================================

  const getImageUrl = (
    image
  ) => {

    if (!image) {
      return null;
    }


    if (
      image.startsWith('http://') ||
      image.startsWith('https://')
    ) {
      return image;
    }


    if (
      image.startsWith('/')
    ) {
      return `${API_BASE_URL}${image}`;
    }


    return `${API_BASE_URL}/${image}`;
  };


  // ==========================================
  // DISPLAY NAME
  // ==========================================

  const getMemberName = (
    member
  ) => {

    if (!member) {
      return '-';
    }


    if (isKhmer) {

      return (
        member.name_km ||
        member.name_en ||
        member.name ||
        '-'
      );
    }


    return (
      member.name_en ||
      member.name_km ||
      member.name ||
      '-'
    );
  };


  // ==========================================
  // DISPLAY POSITION
  // ==========================================

  const getMemberPosition = (
    member
  ) => {

    if (!member) {
      return '-';
    }


    if (isKhmer) {

      return (
        member.position_km ||
        member.position_en ||
        member.position ||
        '-'
      );
    }


    return (
      member.position_en ||
      member.position_km ||
      member.position ||
      '-'
    );
  };


  // ==========================================
  // DISPLAY BIO
  // ==========================================

  const getMemberBio = (
    member
  ) => {

    if (!member) {
      return '';
    }


    if (isKhmer) {

      return (
        member.bio_km ||
        member.bio_en ||
        member.bio ||
        ''
      );
    }


    return (
      member.bio_en ||
      member.bio_km ||
      member.bio ||
      ''
    );
  };


  // ==========================================
  // LOAD
  // ==========================================

  useEffect(() => {

    fetchMembers();

    // eslint-disable-next-line
  }, []);


  // ==========================================
  // CLEAN BLOB
  // ==========================================

  useEffect(() => {

    return () => {

      if (
        imagePreview &&
        imagePreview.startsWith(
          'blob:'
        )
      ) {

        URL.revokeObjectURL(
          imagePreview
        );
      }
    };

  }, [imagePreview]);


  // ==========================================
  // FETCH MEMBERS
  // ==========================================

  const fetchMembers =
    async () => {

      try {

        setLoading(true);


        const response =
          await api.get(
            '/api/leadership/'
          );


        const data =
          response.data;


        if (
          Array.isArray(data)
        ) {

          setMembers(data);

        } else if (
          Array.isArray(
            data?.items
          )
        ) {

          setMembers(
            data.items
          );

        } else {

          setMembers([]);
        }

      } catch (error) {

        console.error(
          'Load leadership error:',
          error
        );


        toast.error(
          error?.response?.data
            ?.detail ||
          tr(
            'leadership.loadFailed',
            'Failed to load leadership team.',
            'មិនអាចផ្ទុកក្រុមថ្នាក់ដឹកនាំបានទេ។'
          )
        );

      } finally {

        setLoading(false);
      }
    };


  // ==========================================
  // RESET FORM
  // ==========================================

  const resetForm = () => {

    setFormData({
      ...initialForm,
    });


    setEditingMember(
      null
    );


    setImageFile(null);


    if (
      imagePreview &&
      imagePreview.startsWith(
        'blob:'
      )
    ) {

      URL.revokeObjectURL(
        imagePreview
      );
    }


    setImagePreview(null);

    setImageRemoved(false);


    if (
      fileInputRef.current
    ) {

      fileInputRef.current.value =
        '';
    }


    setSaving(false);
  };


  // ==========================================
  // ADD
  // ==========================================

  const handleAdd = () => {

    resetForm();

    setShowModal(true);
  };


  // ==========================================
  // CLOSE
  // ==========================================

  const handleCloseModal = () => {

    if (saving) {
      return;
    }


    setShowModal(false);

    resetForm();
  };


  // ==========================================
  // EDIT
  // ==========================================

  const handleEdit = (
    member
  ) => {

    setEditingMember(
      member
    );


    setFormData({

      name_en:
        member.name_en ||
        member.name ||
        '',


      name_km:
        member.name_km ||
        '',


      position_en:
        member.position_en ||
        member.position ||
        '',


      position_km:
        member.position_km ||
        '',


      bio_en:
        member.bio_en ||
        member.bio ||
        '',


      bio_km:
        member.bio_km ||
        '',


      email:
        member.email ||
        '',


      phone:
        member.phone ||
        '',


      facebook_url:
        member.facebook_url ||
        '',


      linkedin_url:
        member.linkedin_url ||
        '',


      is_active:
        member.is_active ??
        true,


      order:
        Number(
          member.order
        ) || 0,
    });


    setImageFile(null);

    setImageRemoved(false);


    if (
      imagePreview &&
      imagePreview.startsWith(
        'blob:'
      )
    ) {

      URL.revokeObjectURL(
        imagePreview
      );
    }


    setImagePreview(
      member.image
        ? getImageUrl(
            member.image
          )
        : null
    );


    if (
      fileInputRef.current
    ) {

      fileInputRef.current.value =
        '';
    }


    setShowModal(true);
  };


  // ==========================================
  // CHANGE
  // ==========================================

  const handleChange = (
    event
  ) => {

    const {
      name,
      value,
      type,
      checked,
    } = event.target;


    setFormData(
      (previous) => ({

        ...previous,

        [name]:
          type === 'checkbox'
            ? checked
            : value,
      })
    );
  };


  // ==========================================
  // IMAGE CHANGE
  // ==========================================

  const handleImageChange = (
    event
  ) => {

    const file =
      event.target.files?.[0];


    if (!file) {
      return;
    }


    const allowedTypes = [
      'image/jpeg',
      'image/jpg',
      'image/png',
      'image/webp',
    ];


    if (
      !allowedTypes.includes(
        file.type
      )
    ) {

      toast.error(
        tr(
          'leadership.invalidImage',
          'Please select a JPG, JPEG, PNG or WEBP image.',
          'សូមជ្រើសរើសរូបភាព JPG, JPEG, PNG ឬ WEBP។'
        )
      );


      event.target.value =
        '';

      return;
    }


    const maxSize =
      5 * 1024 * 1024;


    if (
      file.size > maxSize
    ) {

      toast.error(
        tr(
          'leadership.imageTooLarge',
          'Image must be 5 MB or smaller.',
          'រូបភាពត្រូវមានទំហំ 5 MB ឬតូចជាងនេះ។'
        )
      );


      event.target.value =
        '';

      return;
    }


    if (
      imagePreview &&
      imagePreview.startsWith(
        'blob:'
      )
    ) {

      URL.revokeObjectURL(
        imagePreview
      );
    }


    setImageFile(file);

    setImageRemoved(false);


    setImagePreview(
      URL.createObjectURL(
        file
      )
    );
  };


  // ==========================================
  // REMOVE IMAGE
  // ==========================================

  const handleRemoveImage = () => {

    if (
      imagePreview &&
      imagePreview.startsWith(
        'blob:'
      )
    ) {

      URL.revokeObjectURL(
        imagePreview
      );
    }


    setImageFile(null);

    setImagePreview(null);

    setImageRemoved(true);


    if (
      fileInputRef.current
    ) {

      fileInputRef.current.value =
        '';
    }
  };


  // ==========================================
  // SUBMIT
  // ==========================================

  const handleSubmit =
    async (event) => {

      event.preventDefault();


      // ======================================
      // CURRENT LANGUAGE VALIDATION
      // ======================================

      if (
        !String(
          formData[
            nameField
          ] || ''
        ).trim()
      ) {

        toast.error(
          isKhmer
            ? 'សូមបញ្ចូលឈ្មោះ។'
            : 'Please enter the name.'
        );

        return;
      }


      if (
        !String(
          formData[
            positionField
          ] || ''
        ).trim()
      ) {

        toast.error(
          isKhmer
            ? 'សូមបញ្ចូលតួនាទី។'
            : 'Please enter the position.'
        );

        return;
      }


      // ======================================
      // BACKEND REQUIRES BOTH LANGUAGES
      // ======================================

      if (
        !formData.name_en.trim() ||
        !formData.position_en.trim()
      ) {

        toast.error(
          isKhmer
            ? 'សូមប្ដូរទៅ English ហើយបំពេញឈ្មោះ និងតួនាទីជាភាសាអង់គ្លេស។'
            : 'Please complete the English name and position.'
        );

        return;
      }


      if (
        !formData.name_km.trim() ||
        !formData.position_km.trim()
      ) {

        toast.error(
          isKhmer
            ? 'សូមបំពេញឈ្មោះ និងតួនាទីជាភាសាខ្មែរ។'
            : 'Please switch to Khmer and complete the Khmer name and position.'
        );

        return;
      }


      try {

        setSaving(true);


        const data =
          new FormData();


        // ====================================
        // ENGLISH
        // ====================================

        data.append(
          'name_en',
          formData.name_en.trim()
        );


        data.append(
          'position_en',
          formData.position_en.trim()
        );


        data.append(
          'bio_en',
          formData.bio_en.trim()
        );


        // ====================================
        // KHMER
        // ====================================

        data.append(
          'name_km',
          formData.name_km.trim()
        );


        data.append(
          'position_km',
          formData.position_km.trim()
        );


        data.append(
          'bio_km',
          formData.bio_km.trim()
        );


        // ====================================
        // COMMON
        // ====================================

        data.append(
          'email',
          formData.email.trim()
        );


        data.append(
          'phone',
          formData.phone.trim()
        );


        data.append(
          'facebook_url',
          formData.facebook_url.trim()
        );


        data.append(
          'linkedin_url',
          formData.linkedin_url.trim()
        );


        data.append(
          'is_active',
          String(
            formData.is_active
          )
        );


        data.append(
          'order',
          String(
            Number(
              formData.order
            ) || 0
          )
        );


        if (imageFile) {

          data.append(
            'image',
            imageFile
          );
        }


        if (
          editingMember &&
          imageRemoved &&
          !imageFile
        ) {

          data.append(
            'remove_image',
            'true'
          );
        }


        // ====================================
        // UPDATE
        // ====================================

        if (
          editingMember
        ) {

          await api.put(
            `/api/leadership/${editingMember.id}`,
            data,
            {
              headers: {
                'Content-Type':
                  'multipart/form-data',
              },
            }
          );


          toast.success(
            tr(
              'leadership.updatedSuccess',
              'Leadership member updated successfully.',
              'បានកែប្រែសមាជិកថ្នាក់ដឹកនាំដោយជោគជ័យ។'
            )
          );

        } else {

          // ==================================
          // CREATE
          // ==================================

          await api.post(
            '/api/leadership/',
            data,
            {
              headers: {
                'Content-Type':
                  'multipart/form-data',
              },
            }
          );


          toast.success(
            tr(
              'leadership.createdSuccess',
              'Leadership member added successfully.',
              'បានបន្ថែមសមាជិកថ្នាក់ដឹកនាំដោយជោគជ័យ។'
            )
          );
        }


        setShowModal(false);

        resetForm();

        await fetchMembers();

      } catch (error) {

        console.error(
          'Leadership submit error:',
          error
        );


        const detail =
          error?.response?.data
            ?.detail ||
          error?.response?.data
            ?.message;


        if (
          Array.isArray(detail)
        ) {

          toast.error(
            detail
              .map(
                (item) =>
                  item?.msg ||
                  'Validation error'
              )
              .join(', ')
          );

        } else {

          toast.error(
            detail ||
            tr(
              'common.operationFailed',
              'Failed to save leadership member.',
              'មិនអាចរក្សាទុកសមាជិកថ្នាក់ដឹកនាំបានទេ។'
            )
          );
        }

      } finally {

        setSaving(false);
      }
    };


  // ==========================================
  // DELETE
  // ==========================================

  const handleDelete =
    async (member) => {

      const confirmed =
        window.confirm(
          `${tr(
            'leadership.deleteConfirm',
            'Are you sure you want to delete this leadership member?',
            'តើអ្នកប្រាកដថាចង់លុបសមាជិកថ្នាក់ដឹកនាំនេះមែនទេ?'
          )}\n\n${getMemberName(member)}`
        );


      if (!confirmed) {
        return;
      }


      try {

        await api.delete(
          `/api/leadership/${member.id}`
        );


        toast.success(
          tr(
            'leadership.deletedSuccess',
            'Leadership member deleted successfully.',
            'បានលុបសមាជិកថ្នាក់ដឹកនាំដោយជោគជ័យ។'
          )
        );


        await fetchMembers();

      } catch (error) {

        console.error(
          'Delete leadership error:',
          error
        );


        toast.error(
          error?.response?.data
            ?.detail ||
          tr(
            'leadership.deleteFailed',
            'Failed to delete leadership member.',
            'មិនអាចលុបសមាជិកថ្នាក់ដឹកនាំបានទេ។'
          )
        );
      }
    };


  // ==========================================
  // LOADING
  // ==========================================

  if (loading) {

    return (

      <div
        className="
          min-h-[400px]
          flex
          items-center
          justify-center
        "
      >

        <div
          className="
            text-center
          "
        >

          <div
            className="
              w-11
              h-11

              border-4
              border-blue-200
              border-t-blue-900

              rounded-full

              animate-spin

              mx-auto
            "
          />


          <p
            className="
              text-blue-400
              text-sm

              mt-4
            "
          >
            {
              tr(
                'common.loading',
                'Loading...',
                'កំពុងផ្ទុក...'
              )
            }
          </p>

        </div>

      </div>
    );
  }


  // ==========================================
  // RETURN
  // ==========================================

  return (

    <div
      className={`
        w-full

        ${
          isKhmer
            ? 'font-khmer'
            : 'font-english'
        }
      `}
    >

      {/* ====================================
          HEADER
      ==================================== */}

      <div
        className="
          flex
          flex-col

          sm:flex-row
          sm:items-center
          sm:justify-between

          gap-4

          mb-7
        "
      >

        <div
          className="
            flex
            items-center
            gap-3
          "
        >

          <div
            className="
              w-12
              h-12

              flex
              items-center
              justify-center

              rounded-xl

              bg-blue-900
              text-white

              shadow-sm
            "
          >

            <FiUsers
              size={22}
            />

          </div>


          <div>

            <h1
              className="
                text-2xl
                md:text-3xl

                font-bold

                text-blue-900
              "
            >
              {
                tr(
                  'leadership.title',
                  'Leadership Team',
                  'ក្រុមថ្នាក់ដឹកនាំ'
                )
              }
            </h1>


            <p
              className="
                text-sm
                text-blue-400

                mt-1
              "
            >
              {
                tr(
                  'leadership.subtitle',
                  'Manage SC Academy leadership team',
                  'គ្រប់គ្រងក្រុមថ្នាក់ដឹកនាំ SC Academy'
                )
              }
            </p>

          </div>

        </div>


        <button
          type="button"

          onClick={
            handleAdd
          }

          className="
            inline-flex
            items-center
            justify-center
            gap-2

            h-11

            px-5

            bg-red-600
            hover:bg-red-700

            text-white

            rounded-xl

            text-sm
            font-semibold

            shadow-sm

            transition-all
          "
        >

          <FiPlus
            size={18}
          />


          {
            tr(
              'leadership.addMember',
              'Add Member',
              'បន្ថែមសមាជិក'
            )
          }

        </button>

      </div>


      {/* ====================================
          SUMMARY
      ==================================== */}

      <div
        className="
          grid
          grid-cols-1
          sm:grid-cols-2

          gap-4

          mb-6
        "
      >

        <div
          className="
            bg-white

            border
            border-blue-200

            rounded-2xl

            p-5

            shadow-sm
          "
        >

          <p
            className="
              text-sm
              text-blue-400
            "
          >
            {
              tr(
                'leadership.totalMembers',
                'Total Members',
                'សមាជិកសរុប'
              )
            }
          </p>


          <p
            className="
              text-3xl
              font-bold
              text-blue-900

              mt-2
            "
          >
            {members.length}
          </p>

        </div>


        <div
          className="
            bg-white

            border
            border-blue-200

            rounded-2xl

            p-5

            shadow-sm
          "
        >

          <p
            className="
              text-sm
              text-blue-400
            "
          >
            {
              tr(
                'leadership.activeMembers',
                'Active Members',
                'សមាជិកសកម្ម'
              )
            }
          </p>


          <p
            className="
              text-3xl
              font-bold
              text-blue-900

              mt-2
            "
          >
            {
              members.filter(
                (member) =>
                  member.is_active
              ).length
            }
          </p>

        </div>

      </div>


      {/* ====================================
          MEMBERS
      ==================================== */}

      <div
        className="
          bg-white

          border
          border-blue-200

          rounded-2xl

          shadow-sm

          overflow-hidden
        "
      >

        {
          members.length === 0
            ? (

              <div
                className="
                  py-16
                  px-5

                  text-center
                "
              >

                <FiUsers
                  size={38}

                  className="
                    mx-auto

                    text-blue-200
                  "
                />


                <p
                  className="
                    mt-3

                    text-blue-400
                  "
                >
                  {
                    tr(
                      'common.noData',
                      'No data found',
                      'មិនមានទិន្នន័យ'
                    )
                  }
                </p>

              </div>

            )
            : (

              <div
                className="
                  divide-y
                  divide-blue-100
                "
              >

                {
                  members.map(
                    (member) => (

                      <div
                        key={
                          member.id
                        }

                        className="
                          flex
                          flex-col

                          lg:flex-row
                          lg:items-center

                          gap-4

                          p-5

                          hover:bg-blue-50/40

                          transition
                        "
                      >

                        {/* IMAGE */}

                        <div
                          className="
                            w-20
                            h-20

                            rounded-2xl

                            overflow-hidden

                            bg-blue-50

                            border
                            border-blue-200

                            flex
                            items-center
                            justify-center

                            flex-shrink-0
                          "
                        >

                          {
                            member.image
                              ? (

                                <img
                                  src={
                                    getImageUrl(
                                      member.image
                                    )
                                  }

                                  alt={
                                    getMemberName(
                                      member
                                    )
                                  }

                                  className="
                                    w-full
                                    h-full

                                    object-cover
                                  "
                                />

                              )
                              : (

                                <FiUserPlaceholder />

                              )
                          }

                        </div>


                        {/* INFORMATION */}

                        <div
                          className="
                            flex-1
                            min-w-0
                          "
                        >

                          <div
                            className="
                              flex
                              flex-wrap
                              items-center
                              gap-2
                            "
                          >

                            <h3
                              className="
                                text-lg
                                font-bold

                                text-blue-900
                              "
                            >
                              {
                                getMemberName(
                                  member
                                )
                              }
                            </h3>


                            <span
                              className={`
                                px-2.5
                                py-1

                                rounded-full

                                text-xs
                                font-semibold

                                ${
                                  member.is_active
                                    ? 'bg-blue-50 text-blue-700'
                                    : 'bg-red-50 text-red-600'
                                }
                              `}
                            >
                              {
                                member.is_active
                                  ? tr(
                                      'common.active',
                                      'Active',
                                      'សកម្ម'
                                    )
                                  : tr(
                                      'common.inactive',
                                      'Inactive',
                                      'អសកម្ម'
                                    )
                              }
                            </span>

                          </div>


                          <p
                            className="
                              text-sm
                              font-semibold

                              text-red-600

                              mt-1
                            "
                          >
                            {
                              getMemberPosition(
                                member
                              )
                            }
                          </p>


                          {
                            getMemberBio(
                              member
                            ) && (

                              <p
                                className="
                                  text-sm
                                  text-blue-400

                                  mt-2

                                  line-clamp-2
                                "
                              >
                                {
                                  getMemberBio(
                                    member
                                  )
                                }
                              </p>
                            )
                          }


                          <div
                            className="
                              flex
                              flex-wrap
                              gap-4

                              mt-3
                            "
                          >

                            {
                              member.email && (

                                <div
                                  className="
                                    flex
                                    items-center
                                    gap-1.5

                                    text-xs
                                    text-blue-500
                                  "
                                >

                                  <FiMail />


                                  <span>
                                    {
                                      member.email
                                    }
                                  </span>

                                </div>
                              )
                            }


                            {
                              member.phone && (

                                <div
                                  className="
                                    flex
                                    items-center
                                    gap-1.5

                                    text-xs
                                    text-blue-500
                                  "
                                >

                                  <FiPhone />


                                  <span>
                                    {
                                      member.phone
                                    }
                                  </span>

                                </div>
                              )
                            }

                          </div>

                        </div>


                        {/* ACTIONS */}

                        <div
                          className="
                            flex
                            items-center
                            gap-2
                          "
                        >

                          <button
                            type="button"

                            onClick={() =>
                              handleEdit(
                                member
                              )
                            }

                            className="
                              w-10
                              h-10

                              flex
                              items-center
                              justify-center

                              rounded-xl

                              bg-blue-50
                              text-blue-900

                              hover:bg-blue-900
                              hover:text-white

                              transition
                            "
                          >

                            <FiEdit2
                              size={17}
                            />

                          </button>


                          <button
                            type="button"

                            onClick={() =>
                              handleDelete(
                                member
                              )
                            }

                            className="
                              w-10
                              h-10

                              flex
                              items-center
                              justify-center

                              rounded-xl

                              bg-red-50
                              text-red-600

                              hover:bg-red-600
                              hover:text-white

                              transition
                            "
                          >

                            <FiTrash2
                              size={17}
                            />

                          </button>

                        </div>

                      </div>

                    )
                  )
                }

              </div>
            )
        }

      </div>


      {/* ====================================
          MODAL
      ==================================== */}

      {
        showModal && (

          <div
            className="
              fixed
              inset-0
              z-50

              bg-blue-950/50
              backdrop-blur-sm

              flex
              items-center
              justify-center

              p-4
            "
          >

            <div
              className="
                w-full
                max-w-4xl

                max-h-[92vh]

                bg-white

                rounded-2xl

                shadow-2xl

                overflow-hidden

                flex
                flex-col
              "
            >

              {/* HEADER */}

              <div
                className="
                  flex
                  items-center
                  justify-between

                  gap-4

                  px-6
                  py-5

                  bg-blue-950

                  text-white
                "
              >

                <div
                  className="
                    flex
                    items-center
                    gap-3
                  "
                >

                  <div
                    className="
                      w-11
                      h-11

                      flex
                      items-center
                      justify-center

                      rounded-xl

                      bg-red-600
                    "
                  >

                    {
                      editingMember
                        ? (
                          <FiEdit2 />
                        )
                        : (
                          <FiPlus />
                        )
                    }

                  </div>


                  <div>

                    <p
                      className="
                        text-xs
                        uppercase
                        tracking-wider

                        text-blue-200

                        font-semibold
                      "
                    >
                      {
                        tr(
                          'leadership.title',
                          'Leadership Management',
                          'ការគ្រប់គ្រងថ្នាក់ដឹកនាំ'
                        )
                      }
                    </p>


                    <h2
                      className="
                        text-xl
                        font-bold

                        mt-1
                      "
                    >
                      {
                        editingMember
                          ? tr(
                              'leadership.editMember',
                              'Edit Member',
                              'កែប្រែសមាជិក'
                            )
                          : tr(
                              'leadership.addMember',
                              'Add Member',
                              'បន្ថែមសមាជិក'
                            )
                      }
                    </h2>

                  </div>

                </div>


                <button
                  type="button"

                  onClick={
                    handleCloseModal
                  }

                  disabled={
                    saving
                  }

                  className="
                    w-10
                    h-10

                    flex
                    items-center
                    justify-center

                    rounded-xl

                    bg-white/10

                    hover:bg-white/20

                    transition
                  "
                >

                  <FiX
                    size={21}
                  />

                </button>

              </div>


              {/* BODY */}

              <div
                className="
                  flex-1
                  overflow-y-auto

                  p-6
                "
              >

                <form
                  id="leadership-form"

                  onSubmit={
                    handleSubmit
                  }

                  className="
                    space-y-6
                  "
                >

                  {/* ================================
                      IMAGE
                  ================================ */}

                  <div
                    className="
                      p-5

                      rounded-2xl

                      bg-blue-50

                      border
                      border-blue-200
                    "
                  >

                    <label
                      className="
                        block

                        text-sm
                        font-semibold

                        text-blue-900

                        mb-3
                      "
                    >
                      {
                        tr(
                          'leadership.memberPhoto',
                          'Member Photo',
                          'រូបភាពសមាជិក'
                        )
                      }
                    </label>


                    <div
                      className="
                        flex
                        flex-col

                        sm:flex-row
                        sm:items-center

                        gap-5
                      "
                    >

                      <div
                        className="
                          w-32
                          h-32

                          rounded-2xl

                          bg-white

                          border
                          border-blue-200

                          overflow-hidden

                          flex
                          items-center
                          justify-center

                          flex-shrink-0
                        "
                      >

                        {
                          imagePreview
                            ? (

                              <img
                                src={
                                  imagePreview
                                }

                                alt="Preview"

                                className="
                                  w-full
                                  h-full

                                  object-cover
                                "
                              />

                            )
                            : (

                              <FiImage
                                size={34}

                                className="
                                  text-blue-300
                                "
                              />
                            )
                        }

                      </div>


                      <div
                        className="
                          flex-1
                        "
                      >

                        <input
                          ref={
                            fileInputRef
                          }

                          type="file"

                          accept="
                            image/jpeg,
                            image/jpg,
                            image/png,
                            image/webp
                          "

                          onChange={
                            handleImageChange
                          }

                          className="
                            hidden
                          "

                          id="leadership-image"
                        />


                        <div
                          className="
                            flex
                            flex-wrap
                            gap-2
                          "
                        >

                          <label
                            htmlFor="leadership-image"

                            className="
                              inline-flex
                              items-center
                              gap-2

                              px-4
                              py-2.5

                              bg-blue-900

                              text-white

                              rounded-xl

                              text-sm
                              font-semibold

                              cursor-pointer

                              hover:bg-blue-800

                              transition
                            "
                          >

                            <FiUpload />


                            {
                              tr(
                                'leadership.chooseImage',
                                'Choose Image',
                                'ជ្រើសរើសរូបភាព'
                              )
                            }

                          </label>


                          {
                            imagePreview && (

                              <button
                                type="button"

                                onClick={
                                  handleRemoveImage
                                }

                                className="
                                  px-4
                                  py-2.5

                                  rounded-xl

                                  bg-red-50
                                  text-red-600

                                  text-sm
                                  font-semibold

                                  hover:bg-red-600
                                  hover:text-white

                                  transition
                                "
                              >
                                {
                                  tr(
                                    'leadership.removePhoto',
                                    'Remove Photo',
                                    'ដករូបភាពចេញ'
                                  )
                                }
                              </button>
                            )
                          }

                        </div>


                        <p
                          className="
                            text-xs
                            text-blue-400

                            mt-3
                          "
                        >
                          {
                            tr(
                              'leadership.imageHelp',
                              'JPG, JPEG, PNG or WEBP. Maximum 5 MB.',
                              'JPG, JPEG, PNG ឬ WEBP។ ទំហំអតិបរមា 5 MB។'
                            )
                          }
                        </p>

                      </div>

                    </div>

                  </div>


                  {/* ================================
                      ONE LANGUAGE FORM
                  ================================ */}

                  <div
                    className="
                      border
                      border-blue-200

                      rounded-2xl

                      overflow-hidden
                    "
                  >

                    <div
                      className="
                        flex
                        items-center
                        justify-between

                        gap-3

                        px-5
                        py-4

                        bg-blue-50

                        border-b
                        border-blue-200
                      "
                    >

                      <div
                        className="
                          flex
                          items-center
                          gap-2
                        "
                      >

                        <FiGlobe
                          className="
                            text-blue-900
                          "
                        />


                        <h3
                          className="
                            font-semibold
                            text-blue-900
                          "
                        >
                          {
                            tr(
                              'leadership.content',
                              'Leadership Content',
                              'មាតិកាថ្នាក់ដឹកនាំ'
                            )
                          }
                        </h3>

                      </div>


                      <span
                        className="
                          px-3
                          py-1.5

                          bg-white

                          border
                          border-blue-200

                          rounded-full

                          text-xs
                          font-semibold

                          text-blue-900
                        "
                      >
                        {
                          isKhmer
                            ? 'ខ្មែរ'
                            : 'English'
                        }
                      </span>

                    </div>


                    <div
                      className="
                        p-5

                        space-y-5
                      "
                    >

                      {/* NAME */}

                      <div>

                        <label
                          className="
                            block

                            text-sm
                            font-semibold

                            text-blue-900

                            mb-2
                          "
                        >
                          {
                            tr(
                              'leadership.name',
                              'Name',
                              'ឈ្មោះ'
                            )
                          }

                          <span
                            className="
                              text-red-600
                              ml-1
                            "
                          >
                            *
                          </span>

                        </label>


                        <input
                          type="text"

                          name={
                            nameField
                          }

                          value={
                            formData[
                              nameField
                            ]
                          }

                          onChange={
                            handleChange
                          }

                          placeholder={
                            tr(
                              'leadership.namePlaceholder',
                              'Enter member name',
                              'បញ្ចូលឈ្មោះសមាជិក'
                            )
                          }

                          className="
                            w-full

                            h-12

                            px-4

                            border
                            border-blue-200

                            rounded-xl

                            text-blue-900

                            placeholder:text-blue-300

                            focus:outline-none
                            focus:ring-2
                            focus:ring-blue-900/20
                            focus:border-blue-900
                          "
                        />

                      </div>


                      {/* POSITION */}

                      <div>

                        <label
                          className="
                            block

                            text-sm
                            font-semibold

                            text-blue-900

                            mb-2
                          "
                        >
                          {
                            tr(
                              'leadership.position',
                              'Position',
                              'តួនាទី'
                            )
                          }

                          <span
                            className="
                              text-red-600
                              ml-1
                            "
                          >
                            *
                          </span>

                        </label>


                        <input
                          type="text"

                          name={
                            positionField
                          }

                          value={
                            formData[
                              positionField
                            ]
                          }

                          onChange={
                            handleChange
                          }

                          placeholder={
                            tr(
                              'leadership.positionPlaceholder',
                              'e.g. School Principal',
                              'ឧ. នាយកសាលា'
                            )
                          }

                          className="
                            w-full

                            h-12

                            px-4

                            border
                            border-blue-200

                            rounded-xl

                            text-blue-900

                            placeholder:text-blue-300

                            focus:outline-none
                            focus:ring-2
                            focus:ring-blue-900/20
                            focus:border-blue-900
                          "
                        />

                      </div>


                      {/* BIO */}

                      <div>

                        <label
                          className="
                            block

                            text-sm
                            font-semibold

                            text-blue-900

                            mb-2
                          "
                        >
                          {
                            tr(
                              'leadership.biography',
                              'Biography',
                              'ជីវប្រវត្តិ'
                            )
                          }
                        </label>


                        <textarea
                          name={
                            bioField
                          }

                          value={
                            formData[
                              bioField
                            ]
                          }

                          onChange={
                            handleChange
                          }

                          rows={5}

                          placeholder={
                            tr(
                              'leadership.biographyPlaceholder',
                              'Enter biography',
                              'បញ្ចូលជីវប្រវត្តិ'
                            )
                          }

                          className="
                            w-full

                            px-4
                            py-3

                            border
                            border-blue-200

                            rounded-xl

                            text-blue-900

                            placeholder:text-blue-300

                            resize-y

                            focus:outline-none
                            focus:ring-2
                            focus:ring-blue-900/20
                            focus:border-blue-900
                          "
                        />

                      </div>

                    </div>

                  </div>


                  {/* ================================
                      CONTACT
                  ================================ */}

                  <div
                    className="
                      border
                      border-blue-200

                      rounded-2xl

                      overflow-hidden
                    "
                  >

                    <div
                      className="
                        px-5
                        py-4

                        bg-blue-50

                        border-b
                        border-blue-200
                      "
                    >

                      <h3
                        className="
                          font-semibold
                          text-blue-900
                        "
                      >
                        {
                          tr(
                            'leadership.contactInformation',
                            'Contact Information',
                            'ព័ត៌មានទំនាក់ទំនង'
                          )
                        }
                      </h3>

                    </div>


                    <div
                      className="
                        p-5

                        grid
                        grid-cols-1
                        md:grid-cols-2

                        gap-5
                      "
                    >

                      <div>

                        <label
                          className="
                            block
                            text-sm
                            font-semibold
                            text-blue-900
                            mb-2
                          "
                        >
                          {
                            tr(
                              'common.email',
                              'Email',
                              'អ៊ីមែល'
                            )
                          }
                        </label>


                        <input
                          type="email"

                          name="email"

                          value={
                            formData.email
                          }

                          onChange={
                            handleChange
                          }

                          placeholder="example@email.com"

                          className="
                            w-full
                            h-12
                            px-4
                            border
                            border-blue-200
                            rounded-xl
                            focus:outline-none
                            focus:border-blue-900
                          "
                        />

                      </div>


                      <div>

                        <label
                          className="
                            block
                            text-sm
                            font-semibold
                            text-blue-900
                            mb-2
                          "
                        >
                          {
                            tr(
                              'common.phone',
                              'Phone',
                              'លេខទូរស័ព្ទ'
                            )
                          }
                        </label>


                        <input
                          type="text"

                          name="phone"

                          value={
                            formData.phone
                          }

                          onChange={
                            handleChange
                          }

                          className="
                            w-full
                            h-12
                            px-4
                            border
                            border-blue-200
                            rounded-xl
                            focus:outline-none
                            focus:border-blue-900
                          "
                        />

                      </div>


                      <div>

                        <label
                          className="
                            block
                            text-sm
                            font-semibold
                            text-blue-900
                            mb-2
                          "
                        >
                          Facebook URL
                        </label>


                        <input
                          type="url"

                          name="facebook_url"

                          value={
                            formData.facebook_url
                          }

                          onChange={
                            handleChange
                          }

                          className="
                            w-full
                            h-12
                            px-4
                            border
                            border-blue-200
                            rounded-xl
                            focus:outline-none
                            focus:border-blue-900
                          "
                        />

                      </div>


                      <div>

                        <label
                          className="
                            block
                            text-sm
                            font-semibold
                            text-blue-900
                            mb-2
                          "
                        >
                          LinkedIn URL
                        </label>


                        <input
                          type="url"

                          name="linkedin_url"

                          value={
                            formData.linkedin_url
                          }

                          onChange={
                            handleChange
                          }

                          className="
                            w-full
                            h-12
                            px-4
                            border
                            border-blue-200
                            rounded-xl
                            focus:outline-none
                            focus:border-blue-900
                          "
                        />

                      </div>

                    </div>

                  </div>


                  {/* ================================
                      GENERAL
                  ================================ */}

                  <div
                    className="
                      border
                      border-blue-200

                      rounded-2xl

                      p-5
                    "
                  >

                    <div
                      className="
                        grid
                        grid-cols-1
                        md:grid-cols-2

                        gap-5
                      "
                    >

                      <div>

                        <label
                          className="
                            block
                            text-sm
                            font-semibold
                            text-blue-900
                            mb-2
                          "
                        >
                          {
                            tr(
                              'leadership.displayOrder',
                              'Display Order',
                              'លំដាប់បង្ហាញ'
                            )
                          }
                        </label>


                        <input
                          type="number"

                          name="order"

                          min="0"

                          value={
                            formData.order
                          }

                          onChange={
                            handleChange
                          }

                          className="
                            w-full
                            h-12
                            px-4
                            border
                            border-blue-200
                            rounded-xl
                          "
                        />

                      </div>


                      <div>

                        <label
                          className="
                            block
                            text-sm
                            font-semibold
                            text-blue-900
                            mb-2
                          "
                        >
                          {
                            tr(
                              'common.status',
                              'Status',
                              'ស្ថានភាព'
                            )
                          }
                        </label>


                        <div
                          className="
                            h-12

                            px-4

                            border
                            border-blue-200

                            rounded-xl

                            flex
                            items-center
                            justify-between
                          "
                        >

                          <span
                            className="
                              text-sm
                              font-semibold
                              text-blue-900
                            "
                          >
                            {
                              formData.is_active
                                ? tr(
                                    'common.active',
                                    'Active',
                                    'សកម្ម'
                                  )
                                : tr(
                                    'common.inactive',
                                    'Inactive',
                                    'អសកម្ម'
                                  )
                            }
                          </span>


                          <button
                            type="button"

                            onClick={() =>
                              setFormData(
                                (previous) => ({

                                  ...previous,

                                  is_active:
                                    !previous.is_active,
                                })
                              )
                            }

                            className={`
                              relative

                              w-12
                              h-7

                              rounded-full

                              transition

                              ${
                                formData.is_active
                                  ? 'bg-blue-900'
                                  : 'bg-blue-200'
                              }
                            `}
                          >

                            <span
                              className={`
                                absolute

                                top-1

                                w-5
                                h-5

                                bg-white

                                rounded-full

                                shadow

                                transition-all

                                ${
                                  formData.is_active
                                    ? 'left-6'
                                    : 'left-1'
                                }
                              `}
                            />

                          </button>

                        </div>

                      </div>

                    </div>

                  </div>

                </form>

              </div>


              {/* FOOTER */}

              <div
                className="
                  flex
                  items-center
                  justify-end

                  gap-3

                  px-6
                  py-5

                  bg-blue-50

                  border-t
                  border-blue-200
                "
              >

                <button
                  type="button"

                  onClick={
                    handleCloseModal
                  }

                  disabled={
                    saving
                  }

                  className="
                    px-5
                    py-2.5

                    bg-white

                    border
                    border-blue-200

                    rounded-xl

                    text-blue-700

                    font-semibold

                    disabled:opacity-50
                  "
                >
                  {
                    tr(
                      'common.cancel',
                      'Cancel',
                      'បោះបង់'
                    )
                  }
                </button>


                <button
                  type="submit"

                  form="leadership-form"

                  disabled={
                    saving
                  }

                  className="
                    min-w-[150px]

                    px-5
                    py-2.5

                    bg-red-600
                    hover:bg-red-700

                    text-white

                    rounded-xl

                    font-semibold

                    inline-flex
                    items-center
                    justify-center
                    gap-2

                    disabled:opacity-60
                  "
                >

                  {
                    saving
                      ? (

                        <>

                          <span
                            className="
                              w-4
                              h-4

                              border-2
                              border-white/30
                              border-t-white

                              rounded-full

                              animate-spin
                            "
                          />


                          {
                            tr(
                              'common.saving',
                              'Saving...',
                              'កំពុងរក្សាទុក...'
                            )
                          }

                        </>

                      )
                      : editingMember
                        ? (

                          <>

                            <FiEdit2 />


                            {
                              tr(
                                'leadership.updateMember',
                                'Update Member',
                                'រក្សាទុកការកែប្រែ'
                              )
                            }

                          </>

                        )
                        : (

                          <>

                            <FiPlus />


                            {
                              tr(
                                'leadership.addMember',
                                'Add Member',
                                'បន្ថែមសមាជិក'
                              )
                            }

                          </>

                        )
                  }

                </button>

              </div>

            </div>

          </div>
        )
      }

    </div>
  );
};


const FiUserPlaceholder = () => (

  <FiUsers
    size={30}

    className="
      text-blue-300
    "
  />
);


export default AdminLeadership;
